        java.util.LinkedHashSet<String> found = new java.util.LinkedHashSet<>(List.of(sheet));
        java.util.ArrayDeque<String> left = new java.util.ArrayDeque<>(List.of(sheet));
        while (!left.isEmpty()) {
            for (String child : children(left.pop())) {
