export function statusOn(claim: Claim, end: string): ClaimStatus | undefined {
  if (claim.log.length === 0) return claim.status;
  let then: ClaimStatus | undefined;
  for (const line of claim.log) if (line.on <= end) then = line.status;
  return then;
}

