function daysOverdue(claim: Claim, late: Late): number {
  if (!overdue(claim, late)) return 0;
  return Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${late.graceBy(claim)}T00:00:00Z`)) / 86_400_000);
